-- Reviewed senior batch 018; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":4331,"word":"transpire","meaning":"發生","example":"No one expected such a lively discussion to transpire after the presentation.","example_zh":"沒有人預料簡報後會發生如此熱烈的討論。","original_meaning":"發生","original_example":"What transpired?","original_example_zh":"發生了什麼事？"},{"source_id":4332,"word":"treasury","meaning":"國庫","example":"The kingdom's treasury funded repairs to the old bridge.","example_zh":"王國國庫出資修復老橋。","original_meaning":"國庫","original_example":"The US Treasury.","original_example_zh":"美國財政部。"},{"source_id":4333,"word":"treatise","meaning":"論文；專論","example":"The scholar wrote a treatise on the design of public gardens.","example_zh":"學者撰寫一部關於公共花園設計的專論。","original_meaning":"論文","original_example":"A political treatise.","original_example_zh":"一部政治論著。"},{"source_id":4334,"word":"trek","meaning":"長途跋涉","example":"The long trek ended at a quiet mountain village.","example_zh":"長途跋涉結束於寧靜山村。","original_meaning":"長途跋涉","original_example":"A mountain trek.","original_example_zh":"一次登山之旅。"},{"source_id":4335,"word":"tremble","meaning":"顫抖","example":"Her hands began to tremble before the important performance.","example_zh":"重要演出前，她的雙手開始顫抖。","original_meaning":"顫抖","original_example":"Tremble with fear.","original_example_zh":"因恐懼而顫抖。"},{"source_id":4336,"word":"trespass","meaning":"侵入","example":"The guide reminded us not to trespass on the private farmland.","example_zh":"嚮導提醒我們不要擅闖私人農田。","original_meaning":"侵入","original_example":"No trespassing.","original_example_zh":"禁止擅入。"},{"source_id":4337,"word":"trickle","meaning":"滴流","example":"Water began to trickle from the small crack in the pipe.","example_zh":"水開始從管子小裂縫緩緩滴流。","original_meaning":"滴流","original_example":"Water trickled down.","original_example_zh":"水滴淌下。"},{"source_id":4338,"word":"trilogy","meaning":"三部曲","example":"She borrowed the final volume of the adventure trilogy.","example_zh":"她借了冒險三部曲的最後一冊。","original_meaning":"三部曲","original_example":"A film trilogy.","original_example_zh":"電影三部曲。"},{"source_id":4339,"word":"trivial","meaning":"瑣碎的","example":"The tiny scratch was a trivial problem compared with the broken wheel.","example_zh":"相較壞掉的輪子，小刮痕只是瑣碎問題。","original_meaning":"瑣碎的","original_example":"A trivial matter.","original_example_zh":"微不足道的小事。"},{"source_id":4340,"word":"trophy","meaning":"獎杯","example":"The chess team placed its trophy in the school display case.","example_zh":"棋隊把獎盃放入學校展示櫃。","original_meaning":"獎杯","original_example":"Win a trophy.","original_example_zh":"贏得獎盃。"},{"source_id":4341,"word":"truce","meaning":"休戰","example":"The two sides agreed to a truce while peace talks continued.","example_zh":"和平談判持續進行時，雙方同意休戰。","original_meaning":"休戰","original_example":"Declare a truce.","original_example_zh":"宣布停火。"},{"source_id":4342,"word":"tumble","meaning":"跌倒；滾落","example":"The wooden blocks began to tumble into the empty box.","example_zh":"木積木開始滾落到空盒裡。","original_meaning":"跌倒","original_example":"She tumbled down.","original_example_zh":"她跌倒了。"},{"source_id":4343,"word":"tunnel","meaning":"隧道","example":"The train passed through a tunnel beneath the hill.","example_zh":"火車通過山丘下方隧道。","original_meaning":"隧道","original_example":"A railway tunnel.","original_example_zh":"鐵路隧道。"},{"source_id":4344,"word":"turbine","meaning":"渦輪","example":"The flowing water turned the small turbine in the classroom model.","example_zh":"流水帶動教室模型裡的小渦輪。","original_meaning":"渦輪","original_example":"A wind turbine.","original_example_zh":"風力發電機。"},{"source_id":4345,"word":"turf","meaning":"草皮；地盤","example":"The gardeners laid fresh turf around the new playground.","example_zh":"園丁在新遊樂場周圍鋪上新草皮。","original_meaning":"地盤","original_example":"Protect one's turf.","original_example_zh":"捍衛自己的地盤。"},{"source_id":4346,"word":"tutor","meaning":"家教","example":"The tutor helped her understand the geometry problem.","example_zh":"家教幫她理解幾何題。","original_meaning":"家教","original_example":"Hire a tutor.","original_example_zh":"聘請家教。"},{"source_id":4347,"word":"twofold","meaning":"雙重的","example":"The project had a twofold purpose: saving water and creating shade.","example_zh":"專案有雙重目的：節水與創造遮蔭。","original_meaning":"雙重的","original_example":"A twofold increase.","original_example_zh":"增加一倍。"},{"source_id":4348,"word":"saboteur","meaning":"破壞者","example":"The story's saboteur secretly damaged the bridge model before the contest.","example_zh":"故事中的破壞者在比賽前暗中損壞模型橋。","original_meaning":"破壞者","original_example":"Catch the saboteur.","original_example_zh":"抓捕破壞者。"},{"source_id":4349,"word":"saga","meaning":"傳奇","example":"The saga followed one family through generations of voyages.","example_zh":"這部傳奇敘述一家人世代航海的歷程。","original_meaning":"傳奇","original_example":"An epic saga.","original_example_zh":"一部史詩般的傳奇。"},{"source_id":4350,"word":"saliva","meaning":"唾液","example":"The biology model showed the glands that produce saliva.","example_zh":"生物模型展示產生唾液的腺體。","original_meaning":"唾液","original_example":"Produce saliva.","original_example_zh":"分泌唾液。"},{"source_id":4351,"word":"salon","meaning":"沙龍","example":"The old salon became a meeting place for writers and musicians.","example_zh":"老沙龍成為作家與音樂家聚會的場所。","original_meaning":"沙龍","original_example":"A beauty salon.","original_example_zh":"美容沙龍。"},{"source_id":4352,"word":"salvation","meaning":"拯救","example":"The timely donation was the old library's salvation.","example_zh":"及時捐款拯救了老圖書館。","original_meaning":"拯救","original_example":"Seek salvation.","original_example_zh":"尋求救贖。"},{"source_id":4353,"word":"sanctuary","meaning":"庇護所","example":"The wildlife sanctuary protected injured birds during their recovery.","example_zh":"野生動物庇護所在受傷鳥類康復期間保護牠們。","original_meaning":"庇護所","original_example":"A wildlife sanctuary.","original_example_zh":"野生動物保護區。"},{"source_id":4354,"word":"sarcasm","meaning":"諷刺","example":"The teacher explained how sarcasm can hurt someone's feelings.","example_zh":"老師解說諷刺語氣可能傷害別人的感受。","original_meaning":"諷刺","original_example":"Use sarcasm.","original_example_zh":"使用諷刺。"},{"source_id":4355,"word":"scalar","meaning":"純量的","example":"Temperature is a scalar quantity because it has magnitude without direction.","example_zh":"溫度是純量，因為只有大小而沒有方向。","original_meaning":"純量的","original_example":"A scalar quantity.","original_example_zh":"一個標量。"},{"source_id":4356,"word":"scalpel","meaning":"手術刀","example":"The museum displayed an old scalpel among its surgical instruments.","example_zh":"博物館在外科器械中展示一把老手術刀。","original_meaning":"手術刀","original_example":"A surgeon scalpel.","original_example_zh":"外科醫生的手術刀。"},{"source_id":4357,"word":"schematic","meaning":"示意圖","example":"The schematic showed how the model's simple parts connected.","example_zh":"示意圖顯示模型簡單零件的連接方式。","original_meaning":"示意圖","original_example":"A circuit schematic.","original_example_zh":"電路圖。"},{"source_id":4358,"word":"sclerosis","meaning":"硬化","example":"The medical glossary described sclerosis as abnormal hardening of tissue.","example_zh":"醫學詞彙表把硬化解釋為組織異常變硬。","original_meaning":"硬化","original_example":"Multiple sclerosis.","original_example_zh":"多發性硬化症。"},{"source_id":4359,"word":"scourge","meaning":"禍害","example":"The exhibition described plastic waste as a scourge of the coastline.","example_zh":"展覽把塑膠垃圾形容為海岸的禍害。","original_meaning":"禍害","original_example":"The scourge of war.","original_example_zh":"戰爭的禍害。"},{"source_id":4360,"word":"scripture","meaning":"經典；聖經經文","example":"The scholar compared translations of the ancient scripture.","example_zh":"學者比較古老經典的不同譯本。","original_meaning":"經典","original_example":"Read the scriptures.","original_example_zh":"閱讀經文。"},{"source_id":4361,"word":"sculpture","meaning":"雕塑","example":"The students admired the sculpture carved from a single block of stone.","example_zh":"學生欣賞由單塊石頭雕成的雕塑。","original_meaning":"雕塑","original_example":"A marble sculpture.","original_example_zh":"一尊大理石雕塑。"},{"source_id":4362,"word":"secretariat","meaning":"秘書處","example":"The secretariat organized the documents for the international meeting.","example_zh":"秘書處整理國際會議文件。","original_meaning":"秘書處","original_example":"The UN Secretariat.","original_example_zh":"聯合國秘書處。"},{"source_id":4363,"word":"sect","meaning":"教派","example":"The exhibit traced the history of a small religious sect.","example_zh":"展覽追溯一個小型宗教教派的歷史。","original_meaning":"教派","original_example":"A religious sect.","original_example_zh":"一個宗教派別。"},{"source_id":4364,"word":"sedentary","meaning":"久坐的","example":"His sedentary routine involved long hours at a desk.","example_zh":"他的久坐作息包括長時間待在書桌前。","original_meaning":"久坐的","original_example":"A sedentary lifestyle.","original_example_zh":"久坐不動的生活方式。"},{"source_id":4365,"word":"seismic","meaning":"地震的","example":"The instruments recorded seismic activity beneath the region.","example_zh":"儀器記錄該地區地下的地震活動。","original_meaning":"地震的","original_example":"Seismic activity.","original_example_zh":"地震活動。"},{"source_id":4366,"word":"semblance","meaning":"外表；表面樣子","example":"The freshly painted wall gave the old room a semblance of newness.","example_zh":"新刷牆面讓老房間看起來像新的一樣。","original_meaning":"外表","original_example":"A semblance of order.","original_example_zh":"表面上的秩序。"},{"source_id":4367,"word":"sentinel","meaning":"哨兵","example":"The sentinel watched the gate of the old fortress.","example_zh":"哨兵守望古堡大門。","original_meaning":"哨兵","original_example":"A lone sentinel.","original_example_zh":"孤獨的哨兵。"},{"source_id":4368,"word":"sequel","meaning":"續集","example":"The author announced a sequel to her popular adventure novel.","example_zh":"作者宣布將推出受歡迎冒險小說的續集。","original_meaning":"續集","original_example":"A movie sequel.","original_example_zh":"電影續集。"},{"source_id":4369,"word":"sermon","meaning":"佈道","example":"The congregation listened quietly to the sermon.","example_zh":"會眾安靜聆聽佈道。","original_meaning":"佈道","original_example":"Deliver a sermon.","original_example_zh":"講道。"},{"source_id":4370,"word":"sever","meaning":"切斷","example":"The carpenter used scissors to sever the thin cord.","example_zh":"木匠用剪刀剪斷細繩。","original_meaning":"切斷","original_example":"Sever ties.","original_example_zh":"斷絕關係。"},{"source_id":4371,"word":"severity","meaning":"嚴重性","example":"The inspection revealed the severity of the storm damage.","example_zh":"檢查揭示風暴損壞的嚴重程度。","original_meaning":"嚴重性","original_example":"The severity of the problem.","original_example_zh":"問題的嚴重性。"},{"source_id":4372,"word":"sewage","meaning":"汙水","example":"The model showed how sewage travels to a treatment plant.","example_zh":"模型展示汙水如何流向處理廠。","original_meaning":"汙水","original_example":"Treat sewage.","original_example_zh":"處理污水。"},{"source_id":4373,"word":"shaft","meaning":"軸","example":"The turning shaft connected the small wheel to the motor.","example_zh":"轉軸把小輪子與馬達連接。","original_meaning":"軸","original_example":"A mine shaft.","original_example_zh":"礦井。"},{"source_id":4374,"word":"shatter","meaning":"粉碎","example":"The falling cup could shatter on the stone floor.","example_zh":"杯子掉到石地板可能摔碎。","original_meaning":"粉碎","original_example":"Shatter a window.","original_example_zh":"砸碎窗戶。"},{"source_id":4375,"word":"sheriff","meaning":"警長","example":"The sheriff helped coordinate the village's flood preparations.","example_zh":"警長協助統籌村莊防洪準備。","original_meaning":"警長","original_example":"The county sheriff.","original_example_zh":"縣警長。"},{"source_id":4376,"word":"shield","meaning":"盾牌","example":"The museum displayed a wooden shield from the ancient settlement.","example_zh":"博物館展示古聚落的一面木盾。","original_meaning":"盾牌","original_example":"A protective shield.","original_example_zh":"防護盾。"},{"source_id":4377,"word":"shipwreck","meaning":"船難；沉船","example":"The museum preserved objects recovered from a historic shipwreck.","example_zh":"博物館保存從歷史沉船打撈出的物件。","original_meaning":"船難","original_example":"A terrible shipwreck.","original_example_zh":"一場可怕的船難。"},{"source_id":4378,"word":"shrine","meaning":"神殿","example":"The travelers visited a quiet mountain shrine.","example_zh":"旅人參訪安靜的山間神殿。","original_meaning":"神殿","original_example":"A Shinto shrine.","original_example_zh":"神道教神社。"},{"source_id":4379,"word":"silhouette","meaning":"輪廓；剪影","example":"The tree's silhouette stood out against the evening sky.","example_zh":"樹的剪影在暮色天空前十分清楚。","original_meaning":"輪廓","original_example":"A dark silhouette.","original_example_zh":"黑暗的剪影。"},{"source_id":4380,"word":"simulate","meaning":"模擬","example":"The model could simulate rain falling on a hillside.","example_zh":"模型能模擬山坡降雨。","original_meaning":"模擬","original_example":"Simulate the experiment.","original_example_zh":"模擬實驗。"},{"source_id":4381,"word":"skeleton","meaning":"骨骼","example":"The museum displayed the skeleton of a large whale.","example_zh":"博物館展示大型鯨魚骨骼。","original_meaning":"骨骼","original_example":"A human skeleton.","original_example_zh":"人體骨骼。"},{"source_id":4382,"word":"slander","meaning":"誹謗","example":"The false spoken accusation amounted to slander.","example_zh":"那項不實口頭指控構成誹謗。","original_meaning":"誹謗","original_example":"Commit slander.","original_example_zh":"散布誹謗。"},{"source_id":4383,"word":"slump","meaning":"衰退","example":"The town's shops struggled during the economic slump.","example_zh":"經濟衰退期間，城鎮商店經營困難。","original_meaning":"衰退","original_example":"An economic slump.","original_example_zh":"經濟衰退。"},{"source_id":4384,"word":"soar","meaning":"翱翔","example":"The eagle began to soar above the valley.","example_zh":"老鷹開始在山谷上空翱翔。","original_meaning":"翱翔","original_example":"Prices soared.","original_example_zh":"物價飆升。"},{"source_id":4385,"word":"solvent","meaning":"有償付能力的","example":"The company remained solvent because it could meet its financial obligations.","example_zh":"公司能履行財務義務，因此仍有償付能力。","original_meaning":"有償付能力的","original_example":"The company is solvent.","original_example_zh":"這家公司有償付能力。"},{"source_id":4386,"word":"sonar","meaning":"聲納","example":"The research vessel used sonar to map the sea floor.","example_zh":"研究船用聲納繪製海床地形。","original_meaning":"聲納","original_example":"Detect using sonar.","original_example_zh":"使用聲納偵測。"},{"source_id":4387,"word":"sophistication","meaning":"精密","example":"The robot's sophistication impressed the visiting students.","example_zh":"機器人的精密程度令來訪學生讚嘆。","original_meaning":"精密","original_example":"Technical sophistication.","original_example_zh":"技術上的精妙。"},{"source_id":4388,"word":"sovereign","meaning":"主權的","example":"The lesson examined the rights of a sovereign state.","example_zh":"課程探討主權國家的權利。","original_meaning":"主權的","original_example":"A sovereign nation.","original_example_zh":"主權國家。"},{"source_id":4389,"word":"spectator","meaning":"觀眾","example":"Each spectator watched the final match in silence.","example_zh":"每位觀眾安靜觀看決賽。","original_meaning":"觀眾","original_example":"Thousands of spectators.","original_example_zh":"數千名觀眾。"},{"source_id":4390,"word":"spleen","meaning":"脾臟","example":"The anatomy model showed the spleen beside the stomach.","example_zh":"解剖模型展示胃旁的脾臟。","original_meaning":"脾臟","original_example":"The spleen functions.","original_example_zh":"脾臟的功能。"},{"source_id":4391,"word":"sponsor","meaning":"贊助者","example":"A local bookstore became the main sponsor of the reading festival.","example_zh":"當地書店成為閱讀節的主要贊助者。","original_meaning":"贊助者","original_example":"Find a sponsor.","original_example_zh":"尋找贊助商。"},{"source_id":4392,"word":"spore","meaning":"孢子","example":"The enlarged model showed a fern releasing a spore.","example_zh":"放大模型展示蕨類釋放一顆孢子。","original_meaning":"孢子","original_example":"Mushroom spores.","original_example_zh":"蘑菇孢子。"},{"source_id":4393,"word":"stagger","meaning":"搖晃；踉蹌","example":"The tired actor pretended to stagger across the stage.","example_zh":"疲倦的演員在舞臺上假裝步履搖晃。","original_meaning":"搖晃","original_example":"He staggered home.","original_example_zh":"他踉蹌地走回家。"},{"source_id":4394,"word":"stagnation","meaning":"停滯","example":"The lack of new ideas led to stagnation in the project.","example_zh":"缺乏新想法，使專案停滯。","original_meaning":"停滯","original_example":"Economic stagnation.","original_example_zh":"經濟停滯。"},{"source_id":4395,"word":"stakeholder","meaning":"利害關係人","example":"Each stakeholder could comment on the proposed community garden.","example_zh":"每位利害關係人都能對社區花園提案發表意見。","original_meaning":"利害關係人","original_example":"Key stakeholders.","original_example_zh":"主要利害關係人。"},{"source_id":4396,"word":"stamina","meaning":"耐力","example":"The long rehearsal tested the musicians' stamina.","example_zh":"長時間排練考驗樂手耐力。","original_meaning":"耐力","original_example":"Build stamina.","original_example_zh":"培養耐力。"},{"source_id":4397,"word":"standstill","meaning":"停頓","example":"The roadworks brought traffic to a standstill.","example_zh":"道路工程使交通完全停頓。","original_meaning":"停頓","original_example":"Come to a standstill.","original_example_zh":"陷入停滯。"},{"source_id":4398,"word":"starvation","meaning":"飢餓","example":"The relief program aimed to prevent starvation after the crop failure.","example_zh":"救援計畫致力防止歉收後發生飢餓。","original_meaning":"飢餓","original_example":"Die of starvation.","original_example_zh":"餓死。"},{"source_id":4399,"word":"statesman","meaning":"政治家","example":"The respected statesman encouraged peaceful negotiations.","example_zh":"受敬重的政治家鼓勵和平談判。","original_meaning":"政治家","original_example":"A great statesman.","original_example_zh":"一位偉大的政治家。"},{"source_id":4400,"word":"stationary","meaning":"靜止的","example":"The cart remained stationary while we measured its height.","example_zh":"我們測量推車高度時，推車保持靜止。","original_meaning":"靜止的","original_example":"A stationary object.","original_example_zh":"靜止的物體。"},{"source_id":4401,"word":"stature","meaning":"身材","example":"Despite his small stature, the conductor filled the hall with energy.","example_zh":"指揮雖然身形矮小，仍以活力感染整個禮堂。","original_meaning":"身材","original_example":"A man of great stature.","original_example_zh":"一位德高望重的人物。"},{"source_id":4402,"word":"stellar","meaning":"出色的","example":"Her stellar performance delighted the audience.","example_zh":"她出色的演出讓觀眾欣喜。","original_meaning":"出色的","original_example":"A stellar performance.","original_example_zh":"一場精彩的演出。"},{"source_id":4403,"word":"stem","meaning":"莖","example":"The plant's stem held its leaves toward the sunlight.","example_zh":"植物的莖托著葉片朝向陽光。","original_meaning":"莖","original_example":"The stem of a plant.","original_example_zh":"植物的莖。"},{"source_id":4404,"word":"steward","meaning":"管家","example":"The steward carefully managed the historic estate.","example_zh":"管家細心管理那座歷史莊園。","original_meaning":"管家","original_example":"A land steward.","original_example_zh":"土地管理人。"},{"source_id":4405,"word":"stigma","meaning":"污名","example":"The workshop challenged the stigma surrounding mental-health support.","example_zh":"工作坊挑戰尋求心理健康支持所面臨的污名。","original_meaning":"污名","original_example":"Social stigma.","original_example_zh":"社會污名。"},{"source_id":4406,"word":"stipend","meaning":"津貼","example":"The research stipend helped cover her travel expenses.","example_zh":"研究津貼協助支付她的交通開銷。","original_meaning":"津貼","original_example":"Receive a stipend.","original_example_zh":"領取津貼。"},{"source_id":4407,"word":"strait","meaning":"海峽","example":"The strait separated the two large islands.","example_zh":"海峽分隔兩座大島。","original_meaning":"海峽","original_example":"The Taiwan Strait.","original_example_zh":"台灣海峽。"},{"source_id":4408,"word":"strand","meaning":"一股；一縷","example":"A single strand of blue thread lay across the cloth.","example_zh":"布面上橫放著一股藍線。","original_meaning":"一股","original_example":"A strand of hair.","original_example_zh":"一縷頭髮。"},{"source_id":4409,"word":"stratum","meaning":"地層","example":"The geologist examined one stratum of the exposed rock.","example_zh":"地質學家檢查裸露岩壁中的一層地層。","original_meaning":"地層","original_example":"A rock stratum.","original_example_zh":"岩層。"},{"source_id":4410,"word":"strenuous","meaning":"費力的","example":"The strenuous climb left the hikers ready for a rest.","example_zh":"費力攀登後，健行者需要休息。","original_meaning":"費力的","original_example":"Strenuous exercise.","original_example_zh":"劇烈運動。"},{"source_id":4411,"word":"stricture","meaning":"限制","example":"The design had to meet a stricture against blocking the public path.","example_zh":"設計必須遵守不得阻擋公共步道的限制。","original_meaning":"限制","original_example":"Moral strictures.","original_example_zh":"道德規範。"},{"source_id":4412,"word":"stride","meaning":"大步","example":"She crossed the hall with a confident stride.","example_zh":"她邁著自信大步穿過大廳。","original_meaning":"大步","original_example":"Make great strides.","original_example_zh":"取得重大進展。"},{"source_id":4413,"word":"stronghold","meaning":"據點","example":"The old castle served as a stronghold above the valley.","example_zh":"古堡曾是山谷上方的防守據點。","original_meaning":"據點","original_example":"A rebel stronghold.","original_example_zh":"叛軍據點。"},{"source_id":4414,"word":"structure","meaning":"結構","example":"The model revealed the bridge's internal structure.","example_zh":"模型顯示橋梁內部結構。","original_meaning":"結構","original_example":"Social structure.","original_example_zh":"社會結構。"},{"source_id":4415,"word":"stumble","meaning":"絆倒","example":"He began to stumble on the uneven path but caught the handrail.","example_zh":"他在不平步道絆了一下，但抓住扶手。","original_meaning":"絆倒","original_example":"Stumble over a rock.","original_example_zh":"絆到一塊石頭。"},{"source_id":4416,"word":"subdue","meaning":"制伏；抑制；平復","example":"The gentle music helped subdue the group's nervousness.","example_zh":"柔和音樂有助平復大家的緊張。","original_meaning":"制伏","original_example":"Subdue the enemy.","original_example_zh":"擊敗敵人。"},{"source_id":4417,"word":"sublime","meaning":"崇高的；壯麗的","example":"The sublime mountain scenery left the visitors speechless.","example_zh":"崇高壯麗的山景讓訪客說不出話。","original_meaning":"崇高的","original_example":"A sublime landscape.","original_example_zh":"壯麗的風景。"},{"source_id":4418,"word":"submarine","meaning":"潛水艇","example":"The research submarine explored the deep sea.","example_zh":"研究潛水艇探索深海。","original_meaning":"潛水艇","original_example":"A nuclear submarine.","original_example_zh":"一艘核潛艇。"},{"source_id":4419,"word":"submerge","meaning":"沈沒；浸入","example":"We could submerge the small model boat in the clear tank.","example_zh":"我們可以把小模型船浸入透明水槽。","original_meaning":"沈沒","original_example":"The island submerged.","original_example_zh":"島嶼沉沒了。"},{"source_id":4420,"word":"subscribe","meaning":"訂閱","example":"The library decided to subscribe to a new science magazine.","example_zh":"圖書館決定訂閱新科學雜誌。","original_meaning":"訂閱","original_example":"Subscribe to a magazine.","original_example_zh":"訂閱雜誌。"},{"source_id":4421,"word":"subsequent","meaning":"隨後的","example":"The first test failed, but the subsequent test was successful.","example_zh":"第一次測試失敗，但隨後的測試成功。","original_meaning":"隨後的","original_example":"Subsequent events.","original_example_zh":"後續事件。"},{"source_id":4422,"word":"subsidiary","meaning":"子公司","example":"The company opened a subsidiary to manage its overseas workshops.","example_zh":"公司設立子公司，管理海外工坊。","original_meaning":"子公司","original_example":"A wholly-owned subsidiary.","original_example_zh":"一家全資子公司。"},{"source_id":4423,"word":"subsistence","meaning":"生存","example":"The village grew enough crops for basic subsistence.","example_zh":"村莊種植足以維持基本生活的作物。","original_meaning":"生存","original_example":"Subsistence farming.","original_example_zh":"自給自足的農業。"},{"source_id":4424,"word":"substantiate","meaning":"證實","example":"The photographs helped substantiate the historian's account.","example_zh":"照片幫助證實歷史學家的敘述。","original_meaning":"證實","original_example":"Substantiate your claim.","original_example_zh":"為你的主張提供實證。"},{"source_id":4425,"word":"substitute","meaning":"替代品","example":"The recycled board was a useful substitute for new wood.","example_zh":"回收板材是新木材的實用替代品。","original_meaning":"替代品","original_example":"A sugar substitute.","original_example_zh":"一種代糖。"},{"source_id":4426,"word":"suburb","meaning":"郊區","example":"The family moved to a quiet suburb near the city.","example_zh":"那家人搬到靠近城市的安靜郊區。","original_meaning":"郊區","original_example":"Live in the suburbs.","original_example_zh":"住在郊區。"},{"source_id":4427,"word":"subversive","meaning":"顛覆性的","example":"The novel's subversive ideas challenged the fictional ruler's authority.","example_zh":"小說中的顛覆性思想挑戰虛構統治者的權威。","original_meaning":"顛覆性的","original_example":"Subversive activities.","original_example_zh":"顛覆性活動。"},{"source_id":4428,"word":"succession","meaning":"繼承","example":"The museum traced the succession of rulers through family portraits.","example_zh":"博物館透過家族肖像追溯統治者繼承順序。","original_meaning":"繼承","original_example":"A line of succession.","original_example_zh":"繼承順序。"},{"source_id":4429,"word":"suicide","meaning":"自殺","example":"The school organized a suicide prevention workshop with trained counselors.","example_zh":"學校邀受訓輔導員舉辦自殺防治工作坊。","original_meaning":"自殺","original_example":"Prevent suicide.","original_example_zh":"預防自殺。"},{"source_id":4430,"word":"summit","meaning":"高峰會","example":"The leaders met at a summit to discuss protecting the ocean.","example_zh":"領袖在高峰會討論海洋保護。","original_meaning":"高峰會","original_example":"A peace summit.","original_example_zh":"和平峰會。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-transpire-01-v1","level":"senior","word":"transpire","sort_order":1,"sense":"發生","alt_zh":"高中生在模型展簡報後熱烈圍桌交流，成年老師開心傾聽。","example":"No one expected such a lively discussion to transpire after the presentation.","example_zh":"沒有人預料簡報後會發生如此熱烈的討論。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/transpire-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-treasury-01-v1","level":"senior","word":"treasury","sort_order":1,"sense":"國庫","alt_zh":"虛構歷史成年財務官在橋梁模型旁整理國庫資金文件與少量金幣，無數字。","example":"The kingdom's treasury funded repairs to the old bridge.","example_zh":"王國國庫出資修復老橋。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/treasury-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-treatise-01-v1","level":"senior","word":"treatise","sort_order":1,"sense":"論文；專論","alt_zh":"成年學者在圖書館整理厚重學術書稿與花園圖面，文字不可辨識。","example":"The scholar wrote a treatise on the design of public gardens.","example_zh":"學者撰寫一部關於公共花園設計的專論。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/treatise-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-trek-01-v1","level":"senior","word":"trek","sort_order":1,"sense":"長途跋涉","alt_zh":"成年嚮導與高中健行隊沿安全山徑接近溫暖山村，裝備齊全、神情疲倦欣喜。","example":"The long trek ended at a quiet mountain village.","example_zh":"長途跋涉結束於寧靜山村。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/trek-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-tremble-01-v1","level":"senior","word":"tremble","sort_order":1,"sense":"顫抖","alt_zh":"高中小提琴手在後臺緊張地輕握琴弓，成年老師溫柔鼓勵，無身體危害。","example":"Her hands began to tremble before the important performance.","example_zh":"重要演出前，她的雙手開始顫抖。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/tremble-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-trespass-01-v1","level":"senior","word":"trespass","sort_order":1,"sense":"侵入","alt_zh":"成年嚮導帶高中生沿清楚公共步道行走，旁邊私人田地以矮籬分隔。","example":"The guide reminded us not to trespass on the private farmland.","example_zh":"嚮導提醒我們不要擅闖私人農田。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/trespass-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-trickle-01-v1","level":"senior","word":"trickle","sort_order":1,"sense":"滴流","alt_zh":"高中生與老師在安全低壓教具上觀察水管細縫少量滴水，水落入托盤。","example":"Water began to trickle from the small crack in the pipe.","example_zh":"水開始從管子小裂縫緩緩滴流。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/trickle-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-trilogy-01-v1","level":"senior","word":"trilogy","sort_order":1,"sense":"三部曲","alt_zh":"高中女生在圖書館查看三本相同風格冒險小說，拿起最後一冊，無可讀書名。","example":"She borrowed the final volume of the adventure trilogy.","example_zh":"她借了冒險三部曲的最後一冊。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/trilogy-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-trivial-01-v1","level":"senior","word":"trivial","sort_order":1,"sense":"瑣碎的","alt_zh":"成年維修師與高中生檢查推車明顯損壞的輪子，旁邊小刮痕很不起眼。","example":"The tiny scratch was a trivial problem compared with the broken wheel.","example_zh":"相較壞掉的輪子，小刮痕只是瑣碎問題。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/trivial-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-trophy-01-v1","level":"senior","word":"trophy","sort_order":1,"sense":"獎杯","alt_zh":"高中西洋棋隊與成年教練將漂亮獎盃放入玻璃校史櫃，無可讀文字。","example":"The chess team placed its trophy in the school display case.","example_zh":"棋隊把獎盃放入學校展示櫃。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/trophy-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-truce-01-v1","level":"senior","word":"truce","sort_order":1,"sense":"休戰","alt_zh":"虛構歷史成年代表在和平會議桌握手，背景安靜城門外營地停止活動，無武器。","example":"The two sides agreed to a truce while peace talks continued.","example_zh":"和平談判持續進行時，雙方同意休戰。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/truce-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-tumble-01-v1","level":"senior","word":"tumble","sort_order":1,"sense":"跌倒；滾落","alt_zh":"高中生在工坊輕倒小木積木，積木從低處落入桌上盒子，老師在旁。","example":"The wooden blocks began to tumble into the empty box.","example_zh":"木積木開始滾落到空盒裡。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/tumble-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-tunnel-01-v1","level":"senior","word":"tunnel","sort_order":1,"sense":"隧道","alt_zh":"安全鐵道景觀中民用列車穿過山丘隧道入口，高中生從遠方觀景區欣賞。","example":"The train passed through a tunnel beneath the hill.","example_zh":"火車通過山丘下方隧道。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/tunnel-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-turbine-01-v1","level":"senior","word":"turbine","sort_order":1,"sense":"渦輪","alt_zh":"高中生與成年老師觀察透明低壓水流教具中小渦輪轉動，帶亮小燈泡。","example":"The flowing water turned the small turbine in the classroom model.","example_zh":"流水帶動教室模型裡的小渦輪。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/turbine-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-turf-01-v1","level":"senior","word":"turf","sort_order":1,"sense":"草皮；地盤","alt_zh":"成年園丁與高中志工在安全公園鋪放整齊綠色草皮，工具收好。","example":"The gardeners laid fresh turf around the new playground.","example_zh":"園丁在新遊樂場周圍鋪上新草皮。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/turf-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-tutor-01-v1","level":"senior","word":"tutor","sort_order":1,"sense":"家教","alt_zh":"成年家教在明亮圖書室陪高中女生觀察三角形拼板，耐心解說。","example":"The tutor helped her understand the geometry problem.","example_zh":"家教幫她理解幾何題。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/tutor-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-twofold-01-v1","level":"senior","word":"twofold","sort_order":1,"sense":"雙重的","alt_zh":"高中生展示有雨水收集桶與遮蔭棚架的校園花園模型，成年老師讚賞。","example":"The project had a twofold purpose: saving water and creating shade.","example_zh":"專案有雙重目的：節水與創造遮蔭。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/twofold-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-saboteur-01-v1","level":"senior","word":"saboteur","sort_order":1,"sense":"破壞者","alt_zh":"高中文學小組看虛構故事圖卡，已損壞的模型橋放在桌上、遠處成年角色心虛離開，無破壞方法。","example":"The story's saboteur secretly damaged the bridge model before the contest.","example_zh":"故事中的破壞者在比賽前暗中損壞模型橋。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/saboteur-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-saga-01-v1","level":"senior","word":"saga","sort_order":1,"sense":"傳奇","alt_zh":"高中生與長者在圖書館閱讀厚故事書，插畫是不同世代民用帆船與家族照片，無戰鬥。"