ors.","example_zh":"學校邀受訓輔導員舉辦自殺防治工作坊。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/suicide-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-summit-01-v1","level":"senior","word":"summit","sort_order":1,"sense":"高峰會","alt_zh":"虛構成年國際領袖在圓桌會議查看地球與海洋生態模型，無真實人物旗幟。","example":"The leaders met at a summit to discuss protecting the ocean.","example_zh":"領袖在高峰會討論海洋保護。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/summit-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1}]$senior_rows$::jsonb) as r(id text,level text,word text,sort_order integer,sense text,alt_zh text,example text,example_zh text,image_url text,local_path text,style text,version integer) on conflict(id) do nothing;
